VALUES ('tpl_demorequest', 'demo-request', 'Demo request', 'Sales', 'Book a demo and learn exactly what to show before the call.', 'Half of a good demo is knowing what to skip. This asks what they want to see, and each answer opens the one follow-up that makes the demo specific — which integrations, which compliance regime, which system they are migrating from — then hands them straight to your booking link.', '["demo","sales","booking","branching"]', 'MonitorPlay', 'choice', 3, 13, '{"schemaVersion":4,"title":"Demo request","description":"Book a demo and learn exactly what to show before the call.","blocks":[{"id":"blk_demorequ00","ref":"welcome","title":"Let''s get you a demo. Two minutes of questions so we don''t waste yours.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_demorequ01","ref":"contact","title":"Who should we be speaking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_demorequ02","ref":"company","title":"Which company?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_demorequ03","ref":"company_size","title":"How many people work there?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_1_10","label":"1–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_200","label":"51–200","image_key":null},{"id":"opt_201_1000","label":"201–1000","image_key":null},{"id":"opt_1000","label":"1000+","image_key":null}],"allowOther":false},{"id":"blk_demorequ04","ref":"decision_role","title":"What''s your role in the decision?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_decide","label":"I decide","image_key":null},{"id":"opt_i_recommend","label":"I recommend","image_key":null},{"id":"opt_i_m_researching","label":"I''m researching for someone else","image_key":null}],"allowOther":false},{"id":"blk_demorequ05","ref":"demo_focus","title":"What would you most like to see?","description":"Pick the one that matters most — we''ll cover the rest if there''s time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_basics_end","label":"The basics, end to end","image_key":null},{"id":"opt_integrations_with_our","label":"Integrations with our stack","image_key":null},{"id":"opt_security_and_compliance","label":"Security and compliance","image_key":null},{"id":"opt_migrating_from_what","label":"Migrating from what we use now","image_key":null}],"allowOther":false},{"id":"blk_demorequ06","ref":"stack","title":"What does it need to talk to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_salesforce","label":"Salesforce","image_key":null},{"id":"opt_hubspot","label":"HubSpot","image_key":null},{"id":"opt_slack","label":"Slack","image_key":null},{"id":"opt_google_workspace","label":"Google Workspace","image_key":null},{"id":"opt_notion","label":"Notion","image_key":null},{"id":"opt_zapier_or_make","label":"Zapier or Make","image_key":null},{"id":"opt_our_own_api","label":"Our own API","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":false},{"id":"blk_demorequ07","ref":"compliance","title":"Which of these are you being held to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_soc_2","label":"SOC 2","image_key":null},{"id":"opt_iso_27001","label":"ISO 27001","image_key":null},{"id":"opt_gdpr","label":"GDPR","image_key":null},{"id":"opt_hipaa","label":"HIPAA","image_key":null},{"id":"opt_an_internal_security","label":"An internal security review","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_demorequ08","ref":"security_contact","title":"Who runs the security review on your side?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_demorequ09","ref":"migrating_from","title":"What are you moving off?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_demorequ10","ref":"migration_volume","title":"Roughly how much data would come with you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_handful_of","label":"A handful of records","image_key":null},{"id":"opt_hundreds","label":"Hundreds","image_key":null},{"id":"opt_thousands","label":"Thousands","image_key":null},{"id":"opt_millions","label":"Millions","image_key":null}],"allowOther":false},{"id":"blk_demorequ11","ref":"timeline","title":"When would you want this live?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_this_quarter","label":"This quarter","image_key":null},{"id":"opt_later_this_year","label":"Later this year","image_key":null},{"id":"opt_no_date_yet","label":"No date yet","image_key":null}],"allowOther":false},{"id":"blk_demorequ12","ref":"anything_else","title":"Anything the demo should definitely cover?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_demorequ13","ref":"