VALUES ('tpl_quoterequest', 'quote-request', 'Quote request', 'Sales', 'Scope a job well enough to price it without a call.', 'Most quote forms collect a name and a vague description, then cost you a discovery call anyway. This asks the questions the price actually depends on, and which ones those are depends on the job — a new build is scoped differently from a rescue, and ongoing support differently again. The first reply can be a number.', '["quote","pricing","services","branching"]', 'FileText', 'choice', 4, 15, '{"schemaVersion":4,"title":"Quote request","description":"Scope a job well enough to price it without a call.","blocks":[{"id":"blk_quotereq00","ref":"welcome","title":"Tell us what you need and we''ll come back with a price.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_quotereq01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_quotereq02","ref":"email","title":"Where should we send the quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_quotereq03","ref":"company","title":"Company, if there is one?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_quotereq04","ref":"job_type","title":"What kind of work is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_new_build","label":"New build","image_key":null},{"id":"opt_redesign_of_something","label":"Redesign of something existing","image_key":null},{"id":"opt_ongoing_support","label":"Ongoing support","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_quotereq05","ref":"build_scale","title":"Roughly how big is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_single_page","label":"A single page or screen","image_key":null},{"id":"opt_a_handful_of","label":"A handful of pages","image_key":null},{"id":"opt_a_full_site","label":"A full site or product","image_key":null},{"id":"opt_i_genuinely_don","label":"I genuinely don''t know","image_key":null}],"allowOther":false},{"id":"blk_quotereq06","ref":"build_has_design","title":"Is there a design already?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it''s ready","noLabel":"No — we''d need that too"},{"id":"blk_quotereq07","ref":"existing_url","title":"Link to what exists now","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false},{"id":"blk_quotereq08","ref":"redesign_reason","title":"What''s driving the change?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_looks_dated","label":"It looks dated","image_key":null},{"id":"opt_it_doesn_t","label":"It doesn''t convert","image_key":null},{"id":"opt_it_s_hard","label":"It''s hard to maintain","image_key":null},{"id":"opt_the_business_has","label":"The business has changed","image_key":null}],"allowOther":false},{"id":"blk_quotereq09","ref":"keep_content","title":"Are you keeping the existing content?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Mostly, yes","noLabel":"No, it''s all being rewritten"},{"id":"blk_quotereq10","ref":"support_hours","title":"How much help do you expect to need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_few_hours","label":"A few hours a month","image_key":null},{"id":"opt_a_day_or","label":"A day or two a month","image_key":null},{"id":"opt_a_day_a","label":"A day a week","image_key":null},{"id":"opt_more_than_that","label":"More than that","image_key":null}],"allowOther":false},{"id":"blk_quotereq11","ref":"support_response","title":"How fast do you need us to respond?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_same_day","label":"Same day","image_key":null},{"id":"opt_within_two_days","label":"Within two days","image_key":null},{"id":"opt_within_a_week","label":"Within a week","image_key":null}],"allowOther":false},{"id":"blk_quotereq12","ref":"job_description","title":"Describe the job in your own words","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_quotereq13","ref":"budget","title":"What''s your budget range?","description":"A range is fine — it tells us what''s realistic.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5k","label":"Under $5k","image_key":null},{"id":"opt_5k_15k","label":"$5k–$15k","image_key":null},{"id":"opt_15k_50k","label":"$15k–$50k","image_key":null},{"id":"opt_50k","label":"$50k+","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather you suggest","image_key":null}],"allowOther":false},{"id":"blk_quotereq14","ref":"deadline","title":"When would you like it finished?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_quotereq15","ref":"attachments","title":"Anything to share? Briefs, drawings, screenshots.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null