VALUES ('tpl_partnershipinquiry', 'partnership-inquiry', 'Partnership inquiry', 'Sales', 'Sort real partnership proposals from the cold pitches.', 'A partnerships inbox fills with pitches that were never going to fit. Each kind of partnership is asked the one thing that makes it credible — an integration for the API it would use, a reseller for the market it sells into, co-marketing for the size of its audience — and a proposal that can''t answer that is the one you were going to decline anyway.', '["partnerships","bizdev","branching"]', 'Handshake', 'choice', 3, 15, '{"schemaVersion":4,"title":"Partnership inquiry","description":"Sort real partnership proposals from the cold pitches.","blocks":[{"id":"blk_partners00","ref":"welcome","title":"Thinking of working together? Tell us what you have in mind.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_partners01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_partners02","ref":"company_name","title":"And your company?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_partners03","ref":"email","title":"Work email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":true},{"id":"blk_partners04","ref":"website","title":"Link to your site","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false},{"id":"blk_partners05","ref":"partnership_type","title":"What kind of partnership?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_technology_integration","label":"Technology integration