[{"id":"opt_a_joint_webinar","label":"A joint webinar","image_key":null},{"id":"opt_a_guest_post","label":"A guest post or newsletter swap","image_key":null},{"id":"opt_a_case_study","label":"A case study together","image_key":null},{"id":"opt_an_event_or","label":"An event or sponsorship","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_partners12","ref":"agency_clients","title":"How many clients do you look after?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_1_5","label":"1–5","image_key":null},{"id":"opt_6_20","label":"6–20","image_key":null},{"id":"opt_21_50","label":"21–50","image_key":null},{"id":"opt_50","label":"50+","image_key":null}],"allowOther":false},{"id":"blk_partners13","ref":"agency_services","title":"What do you do for them?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_partners14","ref":"outcome","title":"What would a good outcome look like for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_partners15","ref":"timeline","title":"What sort of timeline are you thinking?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_next_few_weeks","label":"Next few weeks","image_key":null},{"id":"opt_this_quarter","label":"This quarter","image_key":null},{"id":"opt_this_year","label":"This year","image_key":null},{"id":"opt_exploring_for_now","label":"Exploring for now","image_key":null}],"allowOther":false}],"endings":[{"id":"end_partners01","ref":"end_thanks","title":"Thanks — we''ll read it properly 🤝","bodyMd":"If there''s a fit, you''ll hear from us within t