VALUES ('tpl_npssurvey', 'nps-survey', 'NPS survey', 'Product', 'Measure loyalty, then ask detractors and promoters different things.', 'The score on its own tells you almost nothing you can act on, and the same follow-up cannot serve both ends of it. Someone who scored a 3 is asked what went wrong; someone who scored a 10 is asked what to quote — so one survey produces a fix list and a testimonial list.', '["nps","loyalty","survey","branching"]', 'Gauge', 'scale', 3, 9, '{"schemaVersion":4,"title":"NPS survey","description":"Measure loyalty, then ask detractors and promoters different things.","blocks":[{"id":"blk_npssurve00","ref":"welcome","title":"One quick question — it takes about twenty seconds.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_npssurve01","ref":"score","title":"How likely are you to recommend us to a friend or colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_npssurve02","ref":"went_wrong","title":"What''s gone wrong?","description":"Be blunt. This is read by the people who can fix it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_npssurve03","ref":"problem_area","title":"Where does the trouble mostly sit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_missing","label":"It''s missing something I need","image_key":null},{"id":"opt_it_s_unreliable","label":"It''s unreliable","image_key":null},{"id":"opt_it_s_hard","label":"It''s hard to use","image_key":null},{"id":"opt_support_hasn_t","label":"Support hasn''t helped","image_key":null},{"id":"opt_it_costs_more","label":"It costs more than it''s worth","image_key":null}],"allowOther":f