VALUES ('tpl_csatsurvey', 'csat-survey', 'Customer satisfaction', 'Product', 'Rate a specific interaction, and dig only where it went badly.', 'CSAT works when it is asked about one thing, straight after that thing happened. A happy answer is three taps and done; an unhappy one opens the questions that make the complaint actionable, and offers a human. Nobody is asked what went wrong when nothing did.', '["csat","feedback","support","branching"]', 'SmilePlus', 'scale', 3, 8, '{"schemaVersion":4,"title":"Customer satisfaction","description":"Rate a specific interaction, and dig only where it went badly.","blocks":[{"id":"blk_csatsurv00","ref":"welcome","title":"How did that go? A couple of questions while it''s fresh.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_csatsurv01","ref":"satisfaction","title":"How satisfied were you overall?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_csatsurv02","ref":"effort","title":"How easy was it to get what you needed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Very difficult","labelHigh":"Very easy"},{"id":"blk_csatsurv03","ref":"resolved","title":"Was your issue fully resolved?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_csatsurv04","ref":"still_wrong","title":"What''s still outstanding?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_csatsurv05","ref":"friction","title":"What got in the way?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_took_too","label":"It took too long","image_key":null},{"id":"opt_i_had_to","label":"I had to repeat myself","image_key":null},{"id":"opt_the_answer_didn","label":"The answer didn''t fit my situation","image_key":null},{"id":"opt_i_was_sent","label":"I was sent to the wrong place","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_csatsurv06","ref":"callback","title":"Would you like someone to pick this up with you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes please","noLabel":"No, I''ll manage"},{"id":"blk_csatsurv07","ref":"callback_email","title":"Where can they reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_csatsurv08","ref":"what_helped","title":"What made the difference?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500}],"endings":[{"id":"end_csatsurv01","ref":"end_thanks","title":"Thanks for telling us ⭐","bodyMd":"","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_csatsurv02","ref":"end_followup","title":"Someone will be in touch 📮","bodyMd":"We''ve flagged this as unresolved. Expect a reply within one working day.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_csatsurv01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"callback_email","target":"end_followup","targetKind":"ending"},{"id":"rl_csatsurv02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":false}],"groups":[]},"from":"resolved","target":"still_wrong","targetKind":"block","branch":"true"},{"id":"rl_csatsurv03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":true}],"groups":[]},"from":"resolved","target":"what_helped","targetKind":"block","branch":"true"},{"id":"rl_csatsurv04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"callback"},"op":"eq","value":false}],"groups":[]},"from":"callback","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
