VALUES ('tpl_productmarketfit', 'product-market-fit', 'Product-market fit survey', 'Product', 'The Sean Ellis question, with a different follow-up for each answer.', 'Ask how disappointed people would be if your product disappeared. Above about forty percent “very disappointed” is the usual fit signal — but the useful part is what each group says next, so the three answers lead to three different conversations instead of one generic one.', '["pmf","research","strategy","branching"]', 'Target', 'scale', 3, 9, '{"schemaVersion":4,"title":"Product-market fit survey","description":"The Sean Ellis question, with a different follow-up for each answer.","blocks":[{"id":"blk_productm00","ref":"welcome","title":"A few questions about how you use us. Honest answers help most.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productm01","ref":"disappointment","title":"How would you feel if you could no longer use this product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_disappointed","label":"Very disappointed","image_key":null},{"id":"opt_somewhat_disappointed","label":"Somewhat disappointed","image_key":null},{"id":"opt_not_disappointed","label":"Not disappointed","image_key":null}],"allowOther":false},{"id":"blk_productm02","ref":"main_benefit","title":"What''s the main benefit you get from it?","description":"In your own words — we use these almost verbatim on the site.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productm03","ref":"who_benefits","title":"What type of person do you think would benefit most from this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_productm04","ref":"whats_missing","title":"What would have to be true for you to be very disappointed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productm05","ref":"alternative","title":"What would you use instead?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_productm06","ref":"improvement","title":"How can we improve it for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_productm07","ref":"usage","title":"How often do you use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_a_few_times_2","label":"A few times a month","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_productm08","ref":"role","title":"What best describes your role?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_founder_or_exec","label":"Founder or exec","image_key":null},{"id":"opt_engineering","label":"Engineering","image_key":null},{"id":"opt_design","label":"Design","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_productm09","ref":"team_size","title":"How big is the team you work in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_200","label":"51–200","image_key":null},{"id":"opt_200","label":"200+","image_key":null}],"allowOther":false}],"endings":[{"id":"end_productm01","ref":"end_thanks","title":"Really useful — thank you 🙏","bodyMd":"","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_productm01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"who_benefits","target":"improvement","targetKind":"block"},{"id":"rl_productm02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"whats_missing","target":"improvement","targetKind":"block"},{"id":"rl_productm03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disappointment"},"op":"eq","value":"opt_very_disappointed"}],"groups":[]},"from":"disappointment","target":"main_benefit","targetKind":"block","branch":"true"},{"id":"rl_productm04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disappointment"},"op":"eq","value":"opt_somewhat_disappointed"}],"groups":[]},"from":"disappointment","target":"whats_missing","targetKind":"block","branch":"true"},{"id":"rl_productm05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disappointment"},"op":"eq","value":"opt_not_disappointed"}],"groups":[]},"from":"disappointment","target":"alternative","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIde