VALUES ('tpl_featurerequest', 'feature-request', 'Feature request', 'Product', 'Capture the problem behind the request, not just the request.', 'People ask for solutions; roadmaps need problems. This asks what they are trying to do and how they work around it today — and when someone says they are blocked right now, it takes that seriously and collects enough to reply to them personally.', '["roadmap","feedback","product","branching"]', 'Lightbulb', 'scale', 3, 10, '{"schemaVersion":4,"title":"Feature request","description":"Capture the problem behind the request, not just the request.","blocks":[{"id":"blk_featurer00","ref":"welcome","title":"Got an idea? Tell us what you''re trying to do and we''ll take it from there.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_featurer01","ref":"request","title":"In one line, what would you like to be able to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_featurer02","ref":"problem","title":"What are you trying to accomplish?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_featurer03","ref":"workaround","title":"How do you handle it today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_featurer04","ref":"area","title":"Which part of the product is this about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_building_and_editing","label":"Building and editing","image_key":null},{"id":"opt_sharing_and_publishing","label":"Sharing and publishing","image_key":null},{"id":"opt_results_and_reporting","label":"Results 