VALUES ('tpl_betasignup', 'beta-signup', 'Beta signup', 'Product', 'Recruit testers who will actually test, sorted by platform.', 'A beta list full of people who never log in is worse than a short one. This asks about their setup, their appetite for rough edges and how much time they can give — and everyone who says they can give real time gets asked the questions that decide the first invite wave.', '["beta","research","recruiting","branching"]', 'FlaskConical', 'scale', 3, 10, '{"schemaVersion":4,"title":"Beta signup","description":"Recruit testers who will actually test, sorted by platform.","blocks":[{"id":"blk_betasign00","ref":"welcome","title":"Want early access? Tell us a little about how you''d use it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_betasign01","ref":"email","title":"Your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_betasign02","ref":"name","title":"And your name?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_betasign03","ref":"company","title":"Where do you work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_betasign04","ref":"platform","title":"Which platforms do you need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_web","label":"Web","image_key":null},{"id":"opt_ios","label":"iOS","image_key":null},{"id":"opt_android","label":"Android","image_key":null},{"id":"opt_desktop","label":"Desktop","image_key":null},{"id":"opt_api_only","label":"API only","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_betasign05","ref":"use_case","title":"What would you try first?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_betasign06","ref":"time_commitment","title":"How much time could you give in the first month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_much_as","label":"As much as it takes","image_key":null},{"id":"opt_a_few_hours","label":"A few hours","image_key":null},{"id":"opt_an_hour_or","label":"An hour or two","image_key":null}],"allowOther":false},{"id":"blk_betasign07","ref":"feedback_style","title":"How would you rather give feedback?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_written_notes_as","label":"Written notes as I go","image_key":null},{"id":"opt_a_call_every","label":"A call every couple of weeks","image_key":null},{"id":"opt_bug_reports_only","label":"Bug reports only","image_key":null},{"id":"opt_screen_recordings","label":"Screen recordings","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false},{"id":"blk_betasign08","ref":"rough_edges","title":"How much roughness can you live with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Must basically work","labelHigh":"Break it, I''ll tell you how"},{"id":"blk_betasign09","ref":"call_slot","title":"Best time for an occasional call?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mornings","label":"Mornings","image_key":null},{"id":"opt_afternoons","label":"Afternoons","image_key":null},{"id":"opt_evenings","label":"Evenings","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather not","image_key":null}],"allowOther":false},{"i