VALUES ('tpl_cancellationsurvey', 'cancellation-survey', 'Cancellation survey', 'Product', 'Find out why people leave, and offer the right thing to the ones you can keep.', 'The exit is the most honest moment you get, and the reason decides what is worth saying next. Price gets a question about what would have worked; a missing feature gets asked which one; “no longer need it” gets left alone. Nobody is talked out of leaving — they are asked the one thing their answer makes worth asking.', '["churn","retention","feedback","branching"]', 'DoorOpen', 'scale', 2, 10, '{"schemaVersion":4,"title":"Cancellation survey","description":"Find out why people leave, and offer the right thing to the ones you can keep.","blocks":[{"id":"blk_cancella00","ref":"welcome","title":"Sorry to see you go. A couple of questions, and then you''re done.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_cancella01","ref":"reason","title":"What''s the main reason you''re cancelling?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_expensive","label":"Too expensive","image_key":null},{"id":"opt_missing_a_feature","label":"Missing a feature I need","image_key":null},{"id":"opt_too_hard_to","label":"Too hard to use","image_key":null},{"id":"opt_found_a_better","label":"Found a better alternative","image_key":null},{"id":"opt_no_longer_need","label":"No longer need it","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_cancella02","ref":"price_fair","title":"What would have felt fair?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_half_what_i","label":"Half what I''m paying","image_key":null},{"id":"opt_a_bit_less","label":"A bit less","image_key":null},{"id":"opt_the_price_is","label":"The price is fine — the value wasn''t","image_key":null},{"id":"opt_a_smaller_plan","label":"A smaller plan would have worked","image_key":null}],"allowOther":false},{"id":"blk_cancella03","ref":"missing_feature","title":"Which feature?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_cancella04","ref":"missing_blocked","title":"Did that block you outright, or just slow you down?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Blocked me","noLabel":"Slowed me down"},{"id":"blk_cancella05","ref":"hard_where","title":"Where did it lose you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_cancella06","ref":"competitor","title":"What are you moving to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_cancella07","ref":"competitor_why","title":"What do they do better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_cancella08","ref":"detail","title":"Anything you''d like to add?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_cancella09","ref":"would_return","title":"Would you consider coming back if we fixed that?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Maybe","noLabel":"Unlikely"},{"id":"blk_cancella10","ref":"keep_in_touch","title":"Want us to let you know when we do?","description":"Only for this — no marketing.","required":false,"visibility":null,"image_ke