VALUES ('tpl_waitlist', 'waitlist', 'Launch waitlist', 'Marketing', 'Collect signups, segment by platform, and find your first testers.', 'An email address alone gives you a number to announce and nothing to act on. This asks what someone is waiting for and which platform they are on, then follows that answer down its own path — so launch day starts with a list already sorted into the builds you have to ship.', '["waitlist","launch","growth","beta"]', 'ListOrdered', 'content', 4, 17, '{"schemaVersion":4,"title":"Launch waitlist","description":"Collect signups, segment by platform, and find your first testers.","blocks":[{"id":"blk_waitlist00","ref":"welcome","title":"Thanks for your interest! Get on the list and we''ll let you know the moment we''re live.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_waitlist01","ref":"email","title":"What''s your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_waitlist02","ref":"name","title":"And your name?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_waitlist03","ref":"role","title":"What best describes you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_founder_or_exec","label":"Founder or exec","image_key":null},{"id":"opt_engineer","label":"Engineer","image_key":null},{"id":"opt_designer","label":"Designer","image_key":null},{"id":"opt_marketer","label":"Marketer","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_student_or_hobbyist","label":"Student or hobbyist","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_waitlist04","ref":"platform","title":"Where would you use it first?","description":"We ship one platform at a time, so this decides who gets invited when.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_iphone_or_ipad","label":"iPhone or iPad","image_key":null},{"id":"opt_android","label":"Android","image_key":null},{"id":"opt_the_web_app","label":"The web app","image_key":null},{"id":"opt_a_browser_extension","label":"A browser extension","image_key":null}],"allowOther":false},{"id":"blk_waitlist05","ref":"ios_version","title":"Which iOS are you on?","description":"TestFlight builds need iOS 16 or later.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_ios_18","label":"iOS 18","image_key":null},{"id":"opt_ios_17","label":"iOS 17","image_key":null},{"id":"opt_ios_16","label":"iOS 16","image_key":null},{"id":"opt_older_or_not","label":"Older, or not sure","image_key":null}],"allowOther":false},{"id":"blk_waitlist06","ref":"ios_testflight","title":"Happy to install a TestFlight build?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, send it","noLabel":"I''ll wait for the App Store"},{"id":"blk_waitlist07","ref":"android_device","title":"Which Android phone do you use?","description":"Pixel 8, Galaxy S24 — anything specific helps us test on the right hardware.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_waitlist08","ref":"android_channel","title":"How would you rather install it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_play_store_beta","label":"Play Store beta channel","image_key":null},{"id":"opt_a_direct_apk","label":"A direct APK","image_key":null},{"id":"opt_wait_for_the","label":"Wait for the public release","image_key":null}],"allowOther":false},{"id":"blk_waitlist09","ref":"web_browser","title":"Which browser do you live in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_chrome","label":"Chrome","image_key":null},{"id":"opt_safari","label":"Safari","image_key":null},{"id":"opt_firefox","label":"Firefox","image_key":null},{"id":"opt_edge","label":"Edge","image_key":null},{"id":"opt_arc","label":"Arc","image_key":null}],"allowOther":false},{"id":"blk_waitlist10","ref":"extension_browser","title":"Which browser should we build the extension for first?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_chrome","label":"Chrome","image_key":null},{"id":"opt_firefox","label":"Firefox","image_key":null},{"id":"opt_safari","label":"Safari","image_key":null},{"id":"opt_edge","label":"Edge","image_key":null}],"allowOther":false},{"id":"blk_waitlist11","ref":"hoping_for","title":"What are you hoping this will solve for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_waitlist12","ref":"current_tool","title":"What do you use for that today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_waitlist13","ref":"pain","title":"How much of a problem is that today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Mild annoyance","labelHigh":"Costs me real time"},{"id":"blk_waitlist14","ref":"early_access","title":"Would you like early access before we launch?","description":"Rougher edges, and your feedback actually changes what ships.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, put me in","noLabel":"I''ll wait for launch"},{"id":"blk_waitlist15","ref":"early_access_why","title":"What would you try first?","description":"Testers who know what they want to do with it are the ones we invite first.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_waitlist16","ref":"referral","title":"How did you hear about us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_friend_or","label":"A friend or colleague","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_search","label":"Search","image_key":null},{"id":"opt_a_newsletter_or","label":"A newsletter or blog","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}],"allowOther":false},{"id":"blk_waitlist17","ref":"consent","title":"Keeping you posted","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"Email me about the launch and early access. I can unsubscribe at any time.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_waitlist01","ref":"end_thanks","title":"You''re in 🎉","bodyMd":"We''ll email you the moment there''s something to try.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_waitlist01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"platform"},"op":"eq","value":"opt_iphone_or_ipad"}],"groups":[]},"from":"platform","target":"ios_version","targetKind":"block","branch":"true"},{"id":"rl_waitlist02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"platform"},"op":"eq","value":"opt_android"}],"groups":[]},"from":"platform","target":"android_device","targetKind":"block","branch":"true"},{"id":"rl_waitlist03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"platform"},"op":"eq","value":"opt_the_web_app"}],"groups":[]},"from":"platform","target":"web_browser","targetKind":"block","branch":"true"},{"id":"rl_waitlist04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"platform"},"op":"eq","value":"opt_a_browser_extension"}],"groups":[]},"from":"platform","target":"extension_browser","targetKind":"block","branch":"true"},{"id":"rl_waitlist05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"early_access"},"op":"eq","value":true}],"groups":[]},"from":"early_access","target":"early_access_why","targetKind":"block","branch":"true"},{"id":"rl_waitlist06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"ios_testflight","target":"hoping_for","targetKind":"block","branch":"true"},{"id":"rl_waitlist07","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"android_channel","target":"hoping_for","targetKind":"block","branch":"true"},{"id":"rl_waitlist08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"web_browser","target":"hoping_for","targetKind":"block","branch":"true"},{"id":"rl_waitlist09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"early_access"},"op":"neq","value":true}],"groups":[]},"from":"early_access","target":"referral","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
