VALUES ('tpl_newslettersignup', 'newsletter-signup', 'Newsletter signup', 'Marketing', 'Subscribe people to the topics they actually want.', 'A single list means every send is wrong for someone. Asking which topics and how often, at the moment of signing up, is the cheapest unsubscribe prevention there is — and someone who came for one specific thing gets asked what it was.', '["newsletter","email","consent","segmentation"]', 'Mail', 'content', 3, 9, '{"schemaVersion":4,"title":"Newsletter signup","description":"Subscribe people to the topics they actually want.","blocks":[{"id":"blk_newslett00","ref":"welcome","title":"Want the newsletter? Tell us what to send and how often.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_newslett01","ref":"email","title":"Your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_newslett02","ref":"first_name","title":"First name, so we''re not writing to a stranger?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_newslett03","ref":"reader_type","title":"What brings you here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_use_the","label":"I use the product","image_key":null},{"id":"opt_i_m_deciding","label":"I''m deciding whether to","image_key":null},{"id":"opt_i_m_here","label":"I''m here for the writing, not the product","image_key":null}],"allowOther":false},{"id":"blk_newslett04","ref":"customer_since","title":"How long have you been using it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_a_few_months","label":"A few months","image_key":null},{"id":"opt_over_a_year","label":"Over a year","image_key":null}],"allowOther":false},{"id":"blk_newslett05","ref":"evaluating_against","title":"What else are you looking at?","description":"No wrong answer — it tells us which comparisons are worth writing.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_newslett06","ref":"writing_found_via","title":"What did you read that brought you here?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_newslett07","ref":"topics","title":"What should we send you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_product_updates","label":"Product updates","image_key":null},{"id":"opt_how_to_guides","label":"How-to guides","image_key":null},{"id":"opt_customer_stories","label":"Customer stories","image_key":null},{"id":"opt_industry_news","label":"Industry news","image_key":null},{"id":"opt_events_and_webinars","label":"Events and webinars","image_key":null},{"id":"opt_engineering_write_ups","label":"Engineering write-ups","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_newslett08","ref":"frequency","title":"How often?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_every_two_weeks","label":"Every two weeks","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null}],"allowOther":false},{"id":"blk_newslett09","ref":"consent","title":"Permission to email you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree to receive marketing emails and understand I can unsubscribe from any of them at any time.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_newslett01","ref":"end_thanks","title":"Subscribed ✉️","bodyMd":"Check your inbox to confirm.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_newslett01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reader_type"},"op":"eq","value":"opt_i_use_the"}],"groups":[]},"from":"reader_type","target":"customer_since","targetKind":"block","branch":"true"},{"id":"rl_newslett02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reader_type"},"op":"eq","value":"opt_i_m_deciding"}],"groups":[]},"from":"reader_type","target":"evaluating_against","targetKind":"block","branch":"true"},{"id":"rl_newslett03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reader_type"},"op":"eq","value":"opt_i_m_here"}],"groups":[]},"from":"reader_type","target":"writing_found_via","targetKind":"block","branch":"true"},{"id":"rl_newslett04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"customer_since","target":"topics","targetKind":"block","branch":"true"},{"id":"rl_newslett05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"evaluating_against","target":"topics","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"