VALUES ('tpl_webinarregistration', 'webinar-registration', 'Webinar registration', 'Marketing', 'Register attendees, and ask the no-shows what would have helped.', 'The best webinar Q&A is written before the webinar starts. This asks what they want covered, and splits the people joining live from the ones who only want the recording — because those two get different emails afterwards and should be told so now.', '["webinar","events","leads"]', 'Video', 'content', 3, 10, '{"schemaVersion":4,"title":"Webinar registration","description":"Register attendees, and ask the no-shows what would have helped.","blocks":[{"id":"blk_webinarr00","ref":"welcome","title":"Save your seat — takes about a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_webinarr01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_webinarr02","ref":"email","title":"Where should we send the joining link?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":true},{"id":"blk_webinarr03","ref":"company","title":"Company?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_webinarr04","ref":"job_title","title":"Job title?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_webinarr05","ref":"familiarity","title":"How familiar are you with the topic?","description":"So the speaker knows how much ground to cover before the interesting part.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_new_to_it","label":"Ne