VALUES ('tpl_contentdownload', 'content-download', 'Content download', 'Marketing', 'Gate a guide without making it feel like a toll booth.', 'Every extra field costs downloads faster than it gains lead quality — so the file is unlocked after four questions, and the two that qualify are asked only of the people already researching a purchase. Everyone else gets their guide and is left alone.', '["lead magnet","content","gated"]', 'Download', 'content', 3, 9, '{"schemaVersion":4,"title":"Content download","description":"Gate a guide without making it feel like a toll booth.","blocks":[{"id":"blk_contentd00","ref":"welcome","title":"Almost there — tell us where to send it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_contentd01","ref":"email","title":"Your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":true},{"id":"blk_contentd02","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_contentd03","ref":"company","title":"Company?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_contentd04","ref":"interest","title":"What brought you here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_researching_a_purchase","label":"Researching a purchase","image_key":null},{"id":"opt_solving_a_specific","label":"Solving a specific problem","image_key":null},{"id":"opt_general_learning","label":"General learning","image_key":null}],"allowOther":false},{"id":"blk_contentd05","ref":"buying_timeline","title":"How soon would you want something in place?","required":false,"visibility":null,