ry":false,"kind":"success","requirements":[]},{"id":"end_contentd02","ref":"end_contact","title":"Guide sent, and we''ll be in touch 📄","bodyMd":"Someone who knows this properly will email you within a working day.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_contentd01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interest"},"op":"eq","value":"opt_researching_a_purchase"}],"groups":[]},"from":"interest","target":"buying_timeline","targetKind":"block","branch":"true"},{"id":"rl_contentd02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interest"},"op":"eq","value":"opt_solving_a_specific"}],"groups":[]},"from":"interest","target":"the_problem","targetKind":"block","branch":"true"},{"id":"rl_contentd03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interest"},"op":"eq","value":"opt_general_learning"}],"groups":[]},"from":"interest","target":"learning_focus","targetKind":"block","branch":"true"},{"id":"rl_contentd04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"wants_call"},"op":"eq","value":true}],"groups":[]},"from":"wants_call","target":"end_contact","targetKind":"ending","branch":"true"},{"id":"rl_contentd05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"wants_call"},"op":"eq","value":false}],"groups":[]},"from":"wants_call","target":"consent","targetKind":"block","branch":"true"},{"id":"rl_contentd06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"the_problem","target":"consent","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"e