VALUES ('tpl_eventrsvp', 'event-rsvp', 'Event RSVP', 'Events', 'Collect RSVPs with plus-ones, dietary notes and travel.', 'Everything the caterer and the door need, in the order a guest thinks about it — and nothing else. Someone who can''t come is asked one kind question and let go in twenty seconds; someone who is coming is walked through guests, food and arrival.', '["rsvp","party","guests","branching"]', 'PartyPopper', 'number', 3, 11, '{"schemaVersion":4,"title":"Event RSVP","description":"Collect RSVPs with plus-ones, dietary notes and travel.","blocks":[{"id":"blk_eventrsv00","ref":"welcome","title":"You''re invited! 🎉 Let us know if you can make it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventrsv01","ref":"name","title":"Your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_eventrsv02","ref":"email","title":"Email, for the details nearer the time?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_eventrsv03","ref":"attending","title":"Will you be joining us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Count me in","noLabel":"Can''t make it"},{"id":"blk_eventrsv04","ref":"guests","title":"How many guests are you bringing?","description":"Not counting yourself. Put 0 if you''re coming alone.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":10,"integerOnly":true},{"id":"blk_eventrsv05","ref":"guest_names","title":"Who are they? One name per line.","description":"For the door list and the place cards.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventrsv06","ref":"dietary","title":"Any dietary requirements in your party?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_none","label":"None","image_key":null},{"id":"opt_vegetarian","label":"Vegetarian","image_key":null},{"id":"opt_vegan","label":"Vegan","image_key":null},{"id":"opt_gluten_free","label":"Gluten-free","image_key":null},{"id":"opt_dairy_free","label":"Dairy-free","image_key":null},{"id":"opt_nut_allergy","label":"Nut allergy","image_key":null},{"id":"opt_other_i_ll","label":"Other — I''ll explain below","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_eventrsv07","ref":"dietary_detail","title":"Tell us about that, so the kitchen gets it right","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_eventrsv08","ref":"arrival","title":"How are you getting here?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_driving_i_ll","label":"Driving — I''ll need parking","image_key":null},{"id":"opt_public_transport","label":"Public transport","image_key":null},{"id":"opt_taxi_or_lift","label":"Taxi or lift","image_key":null},{"id":"opt_walking","label":"Walking","image_key":null}],"allowOther":false},{"id":"blk_eventrsv09","ref":"song","title":"One song that would get you on the dance floor?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_eventrsv10","ref":"cannot_reason","title":"Ah — anything we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_away_that_week","label":"Away that week","image_key"