VALUES ('tpl_eventfeedback', 'event-feedback', 'Post-event feedback', 'Events', 'Rate the parts of an event separately, and dig where the score was low.', 'A single “how was it?” averages a great speaker and a cold room into a seven. A grid tells you which one to fix — and anyone who rated the day three or under is asked what happened, while the people who loved it are asked whether they''d speak next time.', '["feedback","events","matrix","branching"]', 'MessagesSquare', 'number', 3, 10, '{"schemaVersion":4,"title":"Post-event feedback","description":"Rate the parts of an event separately, and dig where the score was low.","blocks":[{"id":"blk_eventfee00","ref":"welcome","title":"Thanks for coming! How did we do?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventfee01","ref":"aspects","title":"How would you rate each part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_speakers","label":"Speakers"},{"id":"opt_row_venue","label":"Venue"},{"id":"opt_row_food_and","label":"Food and drink"},{"id":"opt_row_networking","label":"Networking"},{"id":"opt_row_organisation","label":"Organisation"},{"id":"opt_row_value_for","label":"Value for money"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_eventfee02","ref":"overall","title":"And the day as a whole?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_eventfee03","ref":"what_went_wrong","title":"What let it down?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_eventfee04","ref":"would_refund","title":"Would you like someone to look into your ticket?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes please","noLabel":"No need"},{"id":"blk_eventfee05","ref":"highlight","title":"What was the highlight?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventfee06","ref":"would_speak","title":"Would you consider speaking at the next one?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"I''d be up for it","noLabel":"Not for me"},{"id":"blk_eventfee07","ref":"improve","title":"What should we do differently next time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_eventfee08","ref":"topics_next","title":"What would you want covered next time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_more_technical_depth","label":"More technical depth","image_key":null},{"id":"opt_more_case_studies","label":"More case studies","image_key":null},{"id":"opt_more_hands_on","label":"More hands-on workshops","image_key":null},{"id":"opt_more_time_to","label":"More time to talk to people","image_key":null},{"id":"opt_shorter_sessions","label":"Shorter sessions","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_eventfee09","ref":"return","title":"Would you come to another one?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_eventfee10","ref":"email","title":"Email, if you''d like us to follow up","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false}],"endings":[{"id":"end_eventfee01","ref":"end_thanks","title":"Thank you 🙌","bodyMd":"This genuinely shapes the next one.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventfee01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"would_refund","target":"improve","targetKind":"block"},{"id":"rl_eventfee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":3}],"groups":[]},"from":"overall","target":"what_went_wrong","targetKind":"block","branch":"true"},{"id":"rl_eventfee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":4}],"groups":[]},"from":"overall","target":"highlight","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
