VALUES ('tpl_speakersubmission', 'speaker-submission', 'Call for speakers', 'Events', 'Take talk proposals in a shape a committee can review.', 'Proposals arrive as essays when what a review committee needs is a title, an abstract, a length and a bio — comparable at a glance. First-time speakers are offered a mentor; workshop proposals are asked the things only a workshop needs, like room setup and what attendees must install.', '["cfp","conference","speakers","branching"]', 'Mic', 'number', 5, 16, '{"schemaVersion":4,"title":"Call for speakers","description":"Take talk proposals in a shape a committee can review.","blocks":[{"id":"blk_speakers00","ref":"welcome","title":"Got a talk in you? Tell us about it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_speakers01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_speakers02","ref":"email","title":"Email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_speakers03","ref":"pronouns","title":"Pronouns, for the programme?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_speakers04","ref":"talk_title","title":"Talk title","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_speakers05","ref":"abstract","title":"Abstract — what will people learn?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_speakers06","ref":"takeaways","title":"Three things someone will be able to do afterwards","description":"One per line. This is the part reviewers argue about, so make it concrete.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_speakers07","ref":"format","title":"Preferred format","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_lightning_talk_10","label":"Lightning talk (10 min)","image_key":null},{"id":"opt_standard_talk_30","label":"Standard talk (30 min)","image_key":null},{"id":"opt_workshop_90_min","label":"Workshop (90 min)","image_key":null}],"allowOther":false},{"id":"blk_speakers08","ref":"workshop_prereqs","title":"What must attendees install or know beforehand?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_speakers09","ref":"workshop_capacity","title":"How many people can you handle at once?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":5,"max":200,"integerOnly":true},{"id":"blk_speakers10","ref":"workshop_room","title":"What room setup do you need?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_tables_in_groups","label":"Tables in groups","image_key":null},{"id":"opt_theatre_rows","label":"Theatre rows","image_key":null},{"id":"opt_horseshoe","label":"Horseshoe","image_key":null},{"id":"opt_doesn_t_matter","label":"Doesn''t matter","image_key":null}],"allowOther":false},{"id":"blk_speakers11","ref":"level","title":"Who''s it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_beginner","label":"Beginner","image_key":null},{"id":"opt_intermediate","label":"Intermediate","image_key":null},{"id":"opt_advanced","label":"Advanced","image_key":null}],"allowOther":false},{"id":"blk_speakers12","ref":"bio","title":"A short speaker bio","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_speakers13","ref":"spoken_before","title":"Have you spoken at a conference before?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"This would be my first"},{"id":"blk_speakers14","ref":"previous_talk","title":"Link to a previous talk","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false},{"id":"blk_speakers15","ref":"wants_mentor","title":"Would you like a mentor to help you prepare?","description":"We pair first-time speakers with someone who has done it before. It''s free and it helps.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes please","noLabel":"No thanks"},{"id":"blk_speakers16","ref":"travel_support","title":"Would you need help with travel costs?","description":"Asked of everyone, and it never counts against a proposal.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_speakers01","ref":"end_thanks","title":"Submitted 🎤","bodyMd":"We review proposals in batches and reply to everyone, either way.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_speakers01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_lightning_talk_10"}],"groups":[]},"from":"format","target":"level","targetKind":"block","branch":"true"},{"id":"rl_speakers02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_standard_talk_30"}],"groups":[]},"from":"format","target":"level","targetKind":"block","branch":"true"},{"id":"rl_speakers03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_workshop_90_min"}],"groups":[]},"from":"format","target":"workshop_prereqs","targetKind":"block","branch":"true"},{"id":"rl_speakers04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"spoken_before"},"op":"eq","value":true}],"groups":[]},"from":"spoken_before","target":"previous_talk","targetKind":"block","branch":"true"},{"id":"rl_speakers05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"spoken_before"},"op":"eq","value":false}],"groups":[]},"from":"spoken_before","target":"wants_mentor","targetKind":"block","branch":"true"},{"id":"rl_speakers06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"previous_talk","target":"travel_support","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
