VALUES ('tpl_workshopregistration', 'workshop-registration', 'Workshop registration', 'Events', 'Sign people up, take payment, and check they''re ready for the day.', 'A hands-on workshop goes badly when half the room hasn''t installed anything. This asks about experience and setup so the right prep email goes to the right people — and beginners get walked through the extras while the experienced are left alone.', '["workshop","training","registration","payment"]', 'CalendarCheck', 'number', 4, 12, '{"schemaVersion":4,"title":"Workshop registration","description":"Sign people up, take payment, and check they''re ready for the day.","blocks":[{"id":"blk_workshop00","ref":"welcome","title":"Let''s get you registered — a few details and you''re set.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_workshop01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_workshop02","ref":"email","title":"Email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_workshop03","ref":"organisation","title":"Which organisation, if any?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_workshop04","ref":"session","title":"Which session?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_morning_9_00","label":"Morning — 9:00 to 12:00","image_key":null},{"id":"opt_afternoon_13_00","label":"Afternoon — 13:00 to 16:00","image_key":null},{"id":"opt_evening_18_00","label":"Evening — 18:00 to 21:00","image_key":null}]},{"id":"blk_workshop05","ref":"experience","title":"How comfortable are you with the topic already?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Complete beginner","labelHigh":"Very comfortable"},{"id":"blk_workshop06","ref":"beginner_background","title":"What have you tried so far?","description":"So we know where to start rather than guessing.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_workshop07","ref":"wants_primer","title":"Would you like the pre-reading a week early?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, send it","noLabel":"I''ll be fine"},{"id":"blk_workshop08","ref":"advanced_interest","title":"Anything specific you''re hoping we go deep on?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_workshop09","ref":"setup","title":"What will you be working on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_macos","label":"macOS","image_key":null},{"id":"opt_windows","label":"Windows","image_key":null},{"id":"opt_linux","label":"Linux","image_key":null},{"id":"opt_i_ll_use","label":"I''ll use a loaner machine","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_workshop10","ref":"goal","title":"What do you want to walk out being able to do?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_workshop11","ref":"accessibility","title":"Anything we can do to make the day work better for you?","description":"Access, seating, captions, breaks, food — anything.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_workshop12","ref":"ticket","title":"Secure your seat","description":"Replace this with your own checkout link before publishing.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"payment","method":"link","amountMode":"fixed","amount":149,"currency":"USD","url":"https://example.com/checkout/workshop"}],"endings":[{"id":"end_workshop01","ref":"end_thanks","title":"Registered ✅","bodyMd":"Prep instructions are on their way.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_workshop01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"experience"},"op":"lte","value":2}],"groups":[]},"from":"experience","target":"beginner_background","targetKind":"block","branch":"true"},{"id":"rl_workshop02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"experience"},"op":"gte","value":3}],"groups":[]},"from":"experience","target":"advanced_interest","targetKind":"block","branch":"true"},{"id":"rl_workshop03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"wants_primer","target":"setup","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":