VALUES ('tpl_jobapplication', 'job-application', 'Job application', 'HR', 'Screen candidates, and ask each discipline its own questions.', 'Everything a first-pass review needs and nothing it doesn''t. The role someone picks decides what they are asked next — engineers get a code sample, designers a portfolio walkthrough, sales a number — so one form serves five hiring managers without asking anyone an irrelevant question.', '["hiring","recruiting","candidates","branching"]', 'Briefcase', 'contact', 5, 26, '{"schemaVersion":4,"title":"Job application","description":"Screen candidates, and ask each discipline its own questions.","blocks":[{"id":"blk_jobappli00","ref":"welcome","title":"Glad you''re interested in joining us. Let''s start.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_jobappli01","ref":"name","title":"Your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_jobappli02","ref":"email","title":"Email address?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_jobappli03","ref":"phone","title":"Phone number?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false},{"id":"blk_jobappli04","ref":"location","title":"Where are you based?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_jobappli05","ref":"work_setup","title":"How would you want to work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_fully_remote","label":"Fully remote","image_key":null},{"id":"opt_hybrid","label":"Hybrid","image_key":null},{"id":"opt_in_the_office","label":"In the office","image_key":null}],"allowOther":false},{"id":"blk_jobappli06","ref":"role","title":"Which role are you applying for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_engineering","label":"Engineering","image_key":null},{"id":"opt_design","label":"Design","image_key":null},{"id":"opt_product","label":"Product","image_key":null},{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null}],"allowOther":false},{"id":"blk_jobappli07","ref":"eng_stack","title":"What do you work in most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_typescript_javascript","label":"TypeScript / JavaScript","image_key":null},{"id":"opt_python","label":"Python","image_key":null},{"id":"opt_go","label":"Go","image_key":null},{"id":"opt_rust","label":"Rust","image_key":null},{"id":"opt_java_or_kotlin","label":"Java or Kotlin","image_key":null},{"id":"opt_swift","label":"Swift","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_jobappli08","ref":"eng_code_sample","title":"A link to something you''ve built or shipped","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false},{"id":"blk_jobappli09","ref":"eng_proudest","title":"What''s the hardest thing you''ve debugged, and how did you find it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_jobappli10","ref":"design_portfolio","title":"Link to your portfolio","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false},{"id":"blk_jobappli11","ref":"design_focus","title":"Where are you strongest?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_product_and_interaction","label":"Product and interaction","image_key":null},{"id":"opt_visual_and_brand","label":"Visual and brand","image_key":null},{"id":"opt_design_systems","label":"Design systems","image_key":null},{"id":"opt_research","label":"Research","image_key":null},{"id":"opt_motion","label":"Motion","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_jobappli12","ref":"design_case","title":"Pick one project and tell us what you changed and why","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_jobappli13","ref":"product_shipped","title":"Describe something you shipped and how you decided what to cut","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_jobappli14","ref":"product_metric","title":"What number did you own?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_jobappli15","ref":"sales_quota","title":"What annual quota have you carried, in thousands?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":true,"currency":"USD"},{"id":"blk_jobappli16","ref":"sales_deal_size","title":"What size deals do you usually close?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5k","label":"Under $5k","image_key":null},{"id":"opt_5k_25k","label":"$5k–$25k","image_key":null},{"id":"opt_25k_100k","label":"$25k–$100k","image_key":null},{"id":"opt_100k","label":"$100k+","image_key":null}],"allowOther":false},{"id":"blk_jobappli17","ref":"sales_market","title":"Which market do you know best?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_smb","label":"SMB","image_key":null},{"id":"opt_mid_market","label":"Mid-market","image_key":null},{"id":"opt_enterprise","label":"Enterprise","image_key":null},{"id":"opt_developer_tools","label":"Developer tools","image_key":null}],"allowOther":false},{"id":"blk_jobappli18","ref":"ops_area","title":"Which of these have you owned?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_finance","label":"Finance","image_key":null},{"id":"opt_people_and_hiring","label":"People and hiring","image_key":null},{"id":"opt_legal_and_compliance","label":"Legal and compliance","image_key":null},{"id":"opt_customer_operations","label":"Customer operations","image_key":null},{"id":"opt_tooling_and_systems","label":"Tooling and systems","image_key":null},{"id":"opt_vendor_management","label":"Vendor management","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_jobappli19","ref":"ops_process","title":"Describe a process you fixed and what it cost before","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_jobappli20","ref":"experience_years","title":"How many years of relevant experience?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":60,"integerOnly":true},{"id":"blk_jobappli21","ref":"portfolio","title":"Anything else you''d like us to see?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false},{"id":"blk_jobappli22","ref":"cv","title":"Attach your CV","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","application/msword"],"maxFiles":1,"maxSizeMB":10},{"id":"blk_jobappli23","ref":"motivation","title":"Why do you want to work with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_jobappli24","ref":"notice_period","title":"When could you start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_immediately","label":"Immediately","image_key":null},{"id":"opt_within_a_month","label":"Within a month","image_key":null},{"id":"opt_one_to_three","label":"One to three months","image_key":null},{"id":"opt_longer_than_three","label":"Longer than three months","image_key":null}],"allowOther":false},{"id":"blk_jobappli25","ref":"right_to_work","title":"Do you have the right to work where this role is based?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_jobappli26","ref":"accommodations","title":"Anything we should do to make the process work for you?","description":"Interview format, timing, access — it never counts against an application.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_jobappli01","ref":"end_thanks","title":"Application received 🚀","bodyMd":"We review every application within a week, and reply either way.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_jobappli01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"eng_proudest","target":"experience_years","targetKind":"block"},{"id":"rl_jobappli02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"design_case","target":"experience_years","targetKind":"block"},{"id":"rl_jobappli03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"product_metric","target":"experience_years","targetKind":"block"},{"id":"rl_jobappli04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"sales_market","target":"experience_years","targetKind":"block"},{"id":"rl_jobappli05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"role"},"op":"eq","value":"opt_engineering"}],"groups":[]},"from":"role","target":"eng_stack","targetKind":"block","branch":"true"},{"id":"rl_jobappli06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"role"},"op":"eq","value":"opt_design"}],"groups":[]},"from":"role","target":"design_portfolio","targetKind":"block","branch":"true"},{"id":"rl_jobappli07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"role"},"op":"eq","value":"opt_product"}],"groups":[]},"from":"role","target":"product_shipped","targetKind":"block","branch":"true"},{"id":"rl_jobappli08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"role"},"op":"eq","value":"opt_sales"}],"groups":[]},"from":"role","target":"sales_quota","targetKind":"block","branch":"true"},{"id":"rl_jobappli09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"role"},"op":"eq","value":"opt_operations"}],"groups":[]},"from":"role","target":"ops_area","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,