VALUES ('tpl_employeeonboarding', 'employee-onboarding', 'Employee onboarding', 'HR', 'Collect what a new starter needs before day one.', 'The details that otherwise arrive as five separate emails in the first week — legal name, address, kit, a signature on the handbook. Remote starters get shipping and home-setup questions; office starters get desk and access ones, and neither sees the other''s.', '["onboarding","people ops","new hire","branching"]', 'UserCheck', 'contact', 5, 17, '{"schemaVersion":4,"title":"Employee onboarding","description":"Collect what a new starter needs before day one.","blocks":[{"id":"blk_employee00","ref":"welcome","title":"Welcome aboard! A few details so everything''s ready on your first day.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_employee01","ref":"legal_name","title":"Your full legal name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_employee02","ref":"preferred_name","title":"What should we actually call you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_employee03","ref":"pronouns","title":"Pronouns, for the team directory?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_employee04","ref":"personal_email","title":"A personal email we can reach you on","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_employee05","ref":"phone","title":"Mobile number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false},{"id":"blk_employee06","ref":"start_date","title":"Confirm your start date","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_employee07","ref":"work_location","title":"Where will you be working from?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_remote","label":"Remote","image_key":null},{"id":"opt_the_office","label":"The office","image_key":null},{"id":"opt_a_bit_of","label":"A bit of both","image_key":null}],"allowOther":false},{"id":"blk_employee08","ref":"shipping_address","title":"Where should we ship your kit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal","country"]},{"id":"blk_employee09","ref":"home_setup","title":"What do you already have at home?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_external_monitor","label":"External monitor","image_key":null},{"id":"opt_keyboard_and_mouse","label":"Keyboard and mouse","image_key":null},{"id":"opt_decent_chair","label":"Decent chair","image_key":null},{"id":"opt_headset","label":"Headset","image_key":null},{"id":"opt_webcam","label":"Webcam","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_employee10","ref":"office_site","title":"Which office?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_london","label":"London","image_key":null},{"id":"opt_berlin","label":"Berlin","image_key":null},{"id":"opt_new_york","label":"New York","image_key":null},{"id":"opt_bengaluru","label":"Bengaluru","image_key":null}]},{"id":"blk_employee11","ref":"commute","title":"How will you get in?","description":"So we know whether to sort a parking space or a bike locker.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_public_transport","label":"Public transport","image_key":null},{"id":"opt_driving","label":"Driving","image_key":null},{"id":"opt_cycling","label":"Cycling","image_key":null},{"id":"opt_walking","label":"Walking","image_key":null}],"allowOther":false},{"id":"blk_employee12","ref":"equipment","title":"Which laptop would you like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_macbook_pro","label":"MacBook Pro","image_key":null},{"id":"opt_macbook_air","label":"MacBook Air","image_key":null},{"id":"opt_windows_laptop","label":"Windows laptop","image_key":null},{"id":"opt_linux_laptop","label":"Linux laptop","image_key":null}],"allowOther":false},{"id":"blk_employee13","ref":"tshirt","title":"T-shirt size?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_xs","label":"XS","image_key":null},{"id":"opt_s_2","label":"S","image_key":null},{"id":"opt_m_3","label":"M","image_key":null},{"id":"opt_l_4","label":"L","image_key":null},{"id":"opt_xl","label":"XL","image_key":null},{"id":"opt_xxl","label":"XXL","image_key":null}],"allowOther":false},{"id":"blk_employee14","ref":"dietary","title":"Any dietary requirements for team lunches?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_employee15","ref":"emergency_contact","title":"Emergency contact — name and number","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_employee16","ref":"accessibility","title":"Anything we should set up to make work work for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_employee17","ref":"handbook","title":"Sign to confirm you''ve read the employee handbook","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"signature","drawnNameRequired":true}],"endings":[{"id":"end_employee01","ref":"end_thanks","title":"All set 🎊","bodyMd":"See you on day one — we''ll email the schedule shortly.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_employee01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"home_setup","target":"equipment","targetKind":"block"},{"id":"rl_employee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_location"},"op":"eq","value":"opt_remote"}],"groups":[]},"from":"work_location","target":"shipping_address","targetKind":"block","branch":"true"},{"id":"rl_employee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_location"},"op":"eq","value":"opt_the_office"}],"groups":[]},"from":"work_location","target":"office_site","targetKind":"block","branch":"true"},{"id":"rl_employee04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_location"},"op":"eq","value":"opt_a_bit_of"}],"groups":[]},"from":"work_location","target":"shipping_address","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
