VALUES ('tpl_exitinterview', 'exit-interview', 'Exit interview', 'HR', 'Ask why someone is leaving in a way they can answer honestly.', 'Leaving is when people say what they meant. Structured enough to count across a year of departures, open enough to catch what no option covers — and the follow-up follows the reason, so someone leaving over their manager is not asked about the salary bands.', '["retention","people ops","offboarding","branching"]', 'LogOut', 'contact', 3, 12, '{"schemaVersion":4,"title":"Exit interview","description":"Ask why someone is leaving in a way they can answer honestly.","blocks":[{"id":"blk_exitinte00","ref":"welcome","title":"Before you go — your honest answers help the people staying. This is confidential.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_exitinte01","ref":"ratings","title":"How would you rate each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_your_manager","label":"Your manager"},{"id":"opt_row_your_team","label":"Your team"},{"id":"opt_row_compensation","label":"Compensation"},{"id":"opt_row_growth_opportunities","label":"Growth opportunities"},{"id":"opt_row_work_life","label":"Work-life balance"},{"id":"opt_row_leadership_and","label":"Leadership and direction"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_exitinte02","ref":"primary_reason","title":"What''s the main reason you''re leaving?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_compensation","label":"Compensation","image_key":null},{"id":"opt_career_growth","label":"Career growth","image_key":null},{"id":"opt_manager_or_team","label":"Manager or team","image_key":null},{"id":"opt_work_life_balance","label":"Work-life balance","image_key":null},{"id":"opt_company_direction","label":"Company direction","image_key":null},{"id":"opt_personal_reasons","label":"Personal reasons","image_key":null}],"allowOther":false},{"id":"blk_exitinte03","ref":"comp_gap","title":"How far off was it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_10","label":"Under 10%","image_key":null},{"id":"opt_10_25","label":"10–25%","image_key":null},{"id":"opt_more_than_25","label":"More than 25%","image_key":null},{"id":"opt_it_wasn_t","label":"It wasn''t the number — it was how it was decided","image_key":null}],"allowOther":false},{"id":"blk_exitinte04","ref":"growth_missing","title":"What did you want to be doing that you weren''t?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_exitinte05","ref":"manager_detail","title":"What would have made the difference?","description":"Goes to HR only, and is never shown to your manager attributed to you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_exitinte06","ref":"raised_it","title":"Did you raise it at the time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_exitinte07","ref":"balance_detail","title":"What tipped it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_hours","label":"Hours","image_key":null},{"id":"opt_always_on_expectations","label":"Always-on expectations","image_key":null},{"id":"opt_travel_or_commute","label":"Travel or commute","image_key":null},{"id":"opt_not_enough_flexibility","label":"Not enough flexibility","image_key":null}],"allowOther":false},{"id":"blk_exitinte08","ref":"what_worked","title":"What worked well here?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_exitinte09","ref":"what_to_change","title":"What would you change?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_exitinte10","ref":"recommend","title":"How likely are you to recommend us as a place to work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_exitinte11","ref":"boomerang","title":"Would you consider working here again one day?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_exitinte12","ref":"next_role","title":"Where are you off to, if you don''t mind saying?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500}],"endings":[{"id":"end_exitinte01","ref":"end_thanks","title":"Thank you — genuinely 🙏","bodyMd":"All the best for what''s next.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_exitinte01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"comp_gap","target":"what_worked","targetKind":"block"},{"id":"rl_exitinte02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"growth_missing","target":"what_worked","targetKind":"block"},{"id":"rl_exitinte03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"raised_it","target":"what_worked","targetKind":"block"},{"id