VALUES ('tpl_engagementpulse', 'engagement-pulse', 'Engagement pulse', 'HR', 'A short, repeatable check that follows up on the low scores.', 'Short enough to send monthly and consistent enough to trend: six scaled statements that stay identical every round. Anyone who scores low on workload or support gets one extra question about it — which is where the anonymised comments worth reading come from.', '["culture","pulse","people ops","branching"]', 'HeartPulse', 'contact', 3, 9, '{"schemaVersion":4,"title":"Engagement pulse","description":"A short, repeatable check that follows up on the low scores.","blocks":[{"id":"blk_engageme00","ref":"welcome","title":"Quick pulse check — anonymous, and under two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_engageme01","ref":"workload","title":"My workload is manageable.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme02","ref":"clarity","title":"I''m clear on what''s expected of me.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme03","ref":"support","title":"I get the support I need from my manager.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme04","ref":"growth","title":"I''m learning and growing here.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme05","ref":"belonging","title":"I can be myself at work.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme06","ref":"enps","title":"How likely are you to recommend us as a place to work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_engageme07","ref":"low_area","title":"Which of these is weighing on you most?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_too_much_work","label":"Too much work","image_key":null},{"id":"opt_unclear_priorities","label":"Unclear priorities","image_key":null},{"id":"opt_not_enough_support","label":"Not enough support","image_key":null},{"id":"opt_no_path_forward","label":"No path forward","image_key":null},{"id":"opt_something_about_the","label":"Something about the team","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_engageme08","ref":"low_detail","title":"What would help most, this month?","description":"Still anonymous. Answers are summarised, never quoted with a name.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_engageme09","ref":"anything_else","title":"Anything else on your mind?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_engageme01","ref":"end_thanks","title":"Thanks 💬","bodyMd":"Results are shared with the whole team.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_engageme01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enps"},"op":"lte","value":6}],"groups":[]},"from":"enps","target":"low_area","targetKind":"block","branch":"true"},{"id":"rl_engageme02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enps"},"op":"gte","value":7}],"groups":[]},"from":"enps","target":"anything_else","targetKind":"block","branch":"true"},{"id":"rl_engageme03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"low_detail","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
