VALUES ('tpl_referralsubmission', 'referral-submission', 'Employee referral', 'HR', 'Make referring someone take a minute, not an afternoon.', 'Referral schemes die on friction. Name, contact, role and one honest line is enough for a recruiter to act on — and when the referrer hasn''t asked the candidate yet, the form says so and takes their word rather than an email address they shouldn''t be sharing.', '["referral","hiring","internal","branching"]', 'Users', 'contact', 3, 10, '{"schemaVersion":4,"title":"Employee referral","description":"Make referring someone take a minute, not an afternoon.","blocks":[{"id":"blk_referral00","ref":"welcome","title":"Know someone great? Put them forward.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_referral01","ref":"referrer","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_referral02","ref":"referrer_team","title":"Which team are you on?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_referral03","ref":"candidate_name","title":"Who are you referring?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_referral04","ref":"has_consent","title":"Do they know you''re referring them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, they''re expecting it","noLabel":"Not yet"},{"id":"blk_referral05","ref":"candidate_contact","title":"How can we reach them? Email or LinkedIn.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_refer