ally","image_key":null}],"allowOther":false}],"endings":[{"id":"end_referral01","ref":"end_thanks","title":"Thanks for the referral 🙌","bodyMd":"We''ll take it from here and keep you posted.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_referral01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"best_approach","target":"role","targetKind":"block"},{"id":"rl_referral02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_consent"},"op":"eq","value":true}],"groups":[]},"from":"has_consent","target":"candidate_contact","targetKind":"block","branch":"true"},{"id":"rl_referral03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_consent"},"op":"eq","value":false}],"groups":[]},"from":"has_consent","target":"will_ask","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
