VALUES ('tpl_bugreport', 'bug-report', 'Bug report', 'Support', 'Get reproducible reports instead of “it''s broken”.', 'Asks for the three things an engineer needs and a reporter always forgets: what they expected, what happened, and the exact steps between. Where it happened decides what is asked next — a browser gets asked about the console, a phone about its model and OS — and anyone who says they cannot work at all is routed straight to a human.', '["bugs","engineering","triage","branching"]', 'Bug', 'advanced', 4, 18, '{"schemaVersion":4,"title":"Bug report","description":"Get reproducible reports instead of “it''s broken”.","blocks":[{"id":"blk_bugrepor00","ref":"welcome","title":"Sorry something''s broken. Let''s get the details down.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bugrepor01","ref":"summary","title":"In one line, what went wrong?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_bugrepor02","ref":"steps","title":"What steps lead to it? Number them if you can.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_bugrepor03","ref":"expected","title":"What did you expect to happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_bugrepor04","ref":"actual","title":"What happened instead?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_bugrepor05","ref":"frequency","title":"How often does it happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_time","label":"Every time","image_key":null},{"id":"opt_most_times","label":"Most times","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null},{"id":"opt_it_happened_once","label":"It happened once","image_key":null}],"allowOther":false},{"id":"blk_bugrepor06","ref":"environment","title":"Where did it happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_a_desktop","label":"In a desktop browser","image_key":null},{"id":"opt_in_the_mobile","label":"In the mobile app","image_key":null},{"id":"opt_through_the_api","label":"Through the API","image_key":null}],"allowOther":false},{"id":"blk_bugrepor07","ref":"browser","title":"Which browser?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_chrome","label":"Chrome","image_key":null},{"id":"opt_safari","label":"Safari","image_key":null},{"id":"opt_firefox","label":"Firefox","image_key":null},{"id":"opt_edge","label":"Edge","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_bugrepor08","ref":"console_errors","title":"Anything red in the developer console?","description":"Right-click → Inspect → Console. Paste whatever is there; if nothing is, say so.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_bugrepor09","ref":"incognito","title":"Does it still happen in a private window?","description":"This is how we tell an extension apart from a real bug in about ten seconds.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, still broken","noLabel":"No, it works there"},{"id":"blk_bugrepor10","ref":"device_model","title":"Which phone or tablet?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_bugrepor11","ref":"os_version","title":"Which OS version?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_bugrepor12","ref":"app_version","title":"Which app version? It''s at the bottom of Settings.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_bugrepor13","ref":"endpoint","title":"Which endpoint?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_bugrepor14","ref":"status_code","title":"What status code came back?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":100,"max":599,"integerOnly":true},{"id":"blk_bugrepor15","ref":"request_id","title":"The request id from the response headers, if you have it","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_bugrepor16","ref":"severity","title":"How badly is this affecting you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_can_t","label":"I can''t work at all","image_key":null},{"id":"opt_there_s_a","label":"There''s a workaround, but it''s painful","image_key":null},{"id":"opt_minor_annoyance","label":"Minor annoyance","image_key":null}],"allowOther":false},{"id":"blk_bugrepor17","ref":"screenshot","title":"A screenshot or recording, if you have one","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"maxFiles":3,"maxSizeMB":25},{"id":"blk_bugrepor18","ref":"email","title":"Where should we reply?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false}],"endings":[{"id":"end_bugrepor01","ref":"end_thanks","title":"Reported 🐛","bodyMd":"Thanks — a real person reads every one of these.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bugrepor02","ref":"end_urgent","title":"Flagged as blocking 🚨","bodyMd":"Send a screenshot to support if you have one. Someone is looking at this now.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_bugrepor01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"incognito","target":"severity","targetKind":"block"},{"id":"rl_bugrepor02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"app_version","target":"severity","targetKind":"block"},{"id":"rl_bugrepor03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"environment"},"op":"eq","value":"opt_in_a_desktop"}],"groups":[]},"from":"environment","target":"browser","targetKind":"block","branch":"true"},{"id":"rl_bugrepor04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"environment"},"op":"eq","value":"opt_in_the_mobile"}],"groups":[]},"from":"environment","target":"device_model","targetKind":"block","branch":"true"},{"id":"rl_bugrepor05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"environment"},"op":"eq","value":"opt_through_the_api"}],"groups":[]},"from":"environment","target":"endpoint","targetKind":"block","branch":"true"},{"id":"rl_bugrepor06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"severity"},"op":"eq","value":"opt_i_can_t"}],"groups":[]},"from":"severity","target":"end_urgent","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
