VALUES ('tpl_supportticket', 'support-ticket', 'Support ticket', 'Support', 'Route requests to the right queue, with the details that queue needs.', 'Category asked up front is what lets a ticket reach the right person without a triage pass — and each category can then ask its own thing. Billing gets an invoice number, login gets the error text, a how-to gets a chance to be answered by a link instead of a person.', '["support","helpdesk","triage","branching"]', 'LifeBuoy', 'advanced', 3, 12, '{"schemaVersion":4,"title":"Support ticket","description":"Route requests to the right queue, with the details that queue needs.","blocks":[{"id":"blk_supportt00","ref":"welcome","title":"How can we help? Tell us what''s going on.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_supportt01","ref":"email","title":"The email on your account?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_supportt02","ref":"category","title":"What''s this about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_billing_or_invoices","label":"Billing or invoices","image_key":null},{"id":"opt_account_and_login","label":"Account and login","image_key":null},{"id":"opt_something_isn_t","label":"Something isn''t working","image_key":null},{"id":"opt_how_do_i","label":"How do I…?","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_supportt03","ref":"invoice_number","title":"Which invoice? The number is top-right.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_supportt04","ref":"billing_issue","title":"What''s wrong with it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_charged_the_wrong","label":"Charged the wrong amount","image_key":null},{"id":"opt_charged_twice","label":"Charged twice","image_key":null},{"id":"opt_need_a_vat","label":"Need a VAT or tax number added","image_key":null},{"id":"opt_want_to_change","label":"Want to change plan","image_key":null},{"id":"opt_card_was_declined","label":"Card was declined","image_key":null}],"allowOther":false},{"id":"blk_supportt05","ref":"login_error","title":"What does the error say, word for word?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_supportt06","ref":"login_method","title":"How do you normally sign in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email_and_password","label":"Email and password","image_key":null},{"id":"opt_google","label":"Google","image_key":null},{"id":"opt_a_magic_link","label":"A magic link","image_key":null},{"id":"opt_sso","label":"SSO","image_key":null}],"allowOther":false},{"id":"blk_supportt07","ref":"broken_where","title":"Where in the product?","description":"The page name or the URL is perfect.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_supportt08","ref":"broken_since","title":"Since when?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_now","label":"Just now","image_key":null},{"id":"opt_today","label":"Today","image_key":null},{"id":"opt_this_week","label":"This week","image_key":null},{"id":"opt_it_s_never","label":"It''s never worked","image_key":null}],"allowOther":false},{"id":"blk_supportt09","ref":"trying_to_do","title":"What are you trying to get done?","description":"Describe the outcome, not the button — we''ll often know a shorter way.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_supportt10","ref":"urgency","title":"How urgent is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_blocking_i_can","label":"Blocking — I can''t work","image_key":null},{"id":"opt_important_but_i","label":"Important, but I can wait a day","image_key":null},{"id":"opt_whenever_you_get","label":"Whenever you get to it","image_key":null}],"allowOther":false},{"id":"blk_supportt11","ref":"description","title":"Anything else we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_supportt12","ref":"attachment","title":"Anything to attach?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":3,"maxSizeMB":10}],"endings":[{"id":"end_supportt01","ref":"end_thanks","title":"Ticket created 🎫","bodyMd":"We reply to most tickets within a few hours.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_supportt01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"billing_issue","target":"urgency","targetKind":"block"},{"id":"rl_supportt02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"login_method","target":"urgency","targetKind":"block"},{"id":"rl_supportt03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"broken_since","target":"urgency","targetKind":"block"},{"id":"rl_supportt04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"trying_to_do","target":"urgency","targetKind":"block"},{"id":"rl_supportt05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_billing_or_invoices"}],"groups":[]},"from":"category","target":"invoice_number","targetKind":"block","branch":"true"},{"id":"rl_supportt06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_account_and_login"}],"groups":[]},"from":"category","target":"login_error","targetKind":"block","branch":"true"},{"id":"rl_supportt07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_something_isn_t"}],"groups":[]},"from":"category","target":"broken_where","targetKind":"block","branch":"true"},{"id":"rl_supportt08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_how_do_i"}],"groups":[]},"from":"category","target":"trying_to_do","targetKind":"block","branch":"true"},{"id":"rl_supportt09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"category","target":"urgency","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
