VALUES ('tpl_contactus', 'contact-us', 'Contact us', 'Support', 'A general enquiry form that sorts the inbox as it fills it.', 'The one form every site needs. What the message is about decides the two or three follow-ups worth asking — a sales enquiry gets company and size, press gets a deadline, careers gets pointed at the actual openings — so nothing arrives needing a reply that just asks for more.', '["contact","general","inbox","branching"]', 'MessageCircle', 'advanced', 3, 12, '{"schemaVersion":4,"title":"Contact us","description":"A general enquiry form that sorts the inbox as it fills it.","blocks":[{"id":"blk_contactu00","ref":"welcome","title":"Hi! What can we help you with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_contactu01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_contactu02","ref":"email","title":"Your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_contactu03","ref":"topic","title":"What''s it about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_sales_enquiry","label":"Sales enquiry","image_key":null},{"id":"opt_support","label":"Support","image_key":null},{"id":"opt_press_or_media","label":"Press or media","image_key":null},{"id":"opt_careers","label":"Careers","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_contactu04","ref":"company","title":"Which company?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_contactu05","ref":"team_size","title":"H