VALUES ('tpl_refundrequest', 'refund-request', 'Refund request', 'Support', 'Handle refunds with the evidence a finance team needs.', 'Order reference, date, reason and preferred resolution — collected once so nobody has to email back asking for them. A damaged item is asked for a photo; a missing one for the tracking status; a duplicate charge for the second transaction. The reason list doubles as a running count of why people ask.', '["refund","billing","ecommerce","branching"]', 'ReceiptText', 'advanced', 3, 13, '{"schemaVersion":4,"title":"Refund request","description":"Handle refunds with the evidence a finance team needs.","blocks":[{"id":"blk_refundre00","ref":"welcome","title":"Let''s sort this out. A few details about the order.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_refundre01","ref":"email","title":"The email used for the order?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_refundre02","ref":"order_reference","title":"Order or invoice number","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_refundre03","ref":"order_date","title":"Roughly when did you order?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_refundre04","ref":"reason","title":"Why are you requesting a refund?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_arrived_damaged_or","label":"Arrived damaged or faulty","image_key":null},{"id":"opt_never_arrived","label":"Never arrived","image_key":null},{"id":"opt_charged_twice","label":"Charged twice","image_key":null},{"id":"opt_not_what_i","label":"Not what I expected","image_key":null},{"id":"opt_changed_my_mind","label":"Changed my mind","image_key":null}],"allowOther":false},{"id":"blk_refundre05","ref":"damage_photos","title":"Photos of the damage","description":"One of the item and one of the packaging is usually enough.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_refundre06","ref":"damage_when","title":"When did you notice?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_on_opening_it","label":"On opening it","image_key":null},{"id":"opt_within_a_few","label":"Within a few days","image_key":null},{"id":"opt_after_using_it","label":"After using it a while","image_key":null}],"allowOther":false},{"id":"blk_refundre07","ref":"tracking_status","title":"What does the tracking say?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_says_delivered_but","label":"Says delivered, but it isn''t here","image_key":null},{"id":"opt_still_in_transit","label":"Still in transit","image_key":null},{"id":"opt_no_tracking_updates","label":"No tracking updates at all","image_key":null},{"id":"opt_i_don_t","label":"I don''t have a tracking number","image_key":null}],"allowOther":false},{"id":"blk_refundre08","ref":"delivery_address","title":"Confirm the delivery address","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"]},{"id":"blk_refundre09","ref":"duplicate_amounts","title":"What amounts and dates do you see on your statement?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_refundre10","ref":"expectation_gap","title":"What was different from what you expected?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_refundre11","ref":"condition","title":"What condition is it in now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_unopened","label":"Unopened","image_key":null},{"id":"opt_opened_but_unused","label":"Opened but unused","image_key":null},{"id":"opt_used","label":"Used","image_key":null},{"id":"opt_damaged","label":"Damaged","image_key":null},{"id":"opt_i_never_received","label":"I never received it","image_key":null}],"allowOther":false},{"id":"blk_refundre12","ref":"resolution","title":"What would you like us to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_refund_to_my","label":"Refund to my original payment method","image_key":null},{"id":"opt_store_credit","label":"Store credit","image_key":null},{"id":"opt_replacement","label":"Replacement","image_key":null}],"allowOther":false},{"id":"blk_refundre13","ref":"detail","title":"Anything else we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_refundre01","ref":"end_thanks","title":"Request received 💳","bodyMd":"Refunds are usually processed within five working days.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_refundre02","ref":"end_finance","title":"Sent to finance 💳","bodyMd":"A duplicate charge is usually reversed within three working days, without anything else from you.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_ref