VALUES ('tpl_courseenrollment', 'course-enrollment', 'Course enrolment', 'Education', 'Enrol students, place them at the right level, and take the fee.', 'Enrolment and placement in one pass. Students who know which course they want go straight through; students who don''t are asked the three questions that place them, and get a recommendation instead of a guess. The fee is collected at the end, once they know what they''re paying for.', '["course","enrolment","students","payment"]', 'GraduationCap', 'text', 5, 18, '{"schemaVersion":4,"title":"Course enrolment","description":"Enrol students, place them at the right level, and take the fee.","blocks":[{"id":"blk_courseen00","ref":"welcome","title":"Welcome! Let''s get you enrolled.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_courseen01","ref":"name","title":"Your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_courseen02","ref":"email","title":"Email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_courseen03","ref":"phone","title":"Mobile number, for timetable changes?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false},{"id":"blk_courseen04","ref":"course","title":"Which course?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_foundations","label":"Foundations","image_key":null},{"id":"opt_intermediate","label":"Intermediate","image_key":null},{"id":"opt_advanced","label":"Advanced","image_key":null},{"id":"opt_not_sure_help","label":"Not sure — help me choose","image_key":null}]},{"id":"blk_courseen05","ref":"why_this_level","title":"What makes that the right level for you?