VALUES ('tpl_studentfeedback', 'student-feedback', 'Student feedback', 'Education', 'End-of-course feedback that separates teaching from material.', 'A course can have excellent material and a rushed delivery, or the reverse — so they are rated apart. Anyone who says the pace was wrong is asked where it went wrong; anyone who would not recommend it is asked what would have to change, which is the only answer that improves the next cohort.', '["teaching","feedback","course","branching"]', 'BookOpen', 'text', 3, 12, '{"schemaVersion":4,"title":"Student feedback","description":"End-of-course feedback that separates teaching from material.","blocks":[{"id":"blk_studentf00","ref":"welcome","title":"You made it to the end! How was it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_studentf01","ref":"aspects","title":"How would you rate each part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_course_material","label":"Course material"},{"id":"opt_row_teaching","label":"Teaching"},{"id":"opt_row_exercises","label":"Exercises"},{"id":"opt_row_pace","label":"Pace"},{"id":"opt_row_support","label":"Support"},{"id":"opt_row_assessment","label":"Assessment"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_studentf02","ref":"overall","title":"And the course overall?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_studentf03","ref":"pace","title":"How was the pace?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_slow","label":"Too slow","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_fast","label":"Too fast","image_key":null}],"allowOther":false},{"id":"blk_studentf04","ref":"slow_where","title":"Which parts dragged?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_studentf05","ref":"fast_where","title":"Where did you start to lose the thread?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_studentf06","ref":"fast_support","title":"Would catch-up sessions have helped?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, definitely","noLabel":"Not really"},{"id":"blk_studentf07","ref":"most_useful","title":"What was most useful?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_studentf08","ref":"least_useful","title":"What would you cut or change?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_studentf09","ref":"confidence_now","title":"How confident do you feel putting this into practice?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_studentf10","ref":"recommend","title":"How likely are you to recommend this course?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_studentf11","ref":"what_would_change_it","title":"What would have to be different for you to recommend it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_studentf12","ref":"quote_ok","title":"May we quote you on the course page?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, with my first name","noLabel":"Please don''t"}],"endings":[{"id":"end_studentf01","ref":"end_thanks","title":"Thank you 📚","bodyMd":"Every cohort improves because of answers like these.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_studentf01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"slow_where","target":"most_useful","targetKind":"block"},{"id":"rl_studentf02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"fast_support","target":"most_useful","targetKind":"block"},{"id":"rl_studentf03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"pace"},"op":"eq","value":"opt_too_slow"}],"groups":[]},"from":"pace","target":"slow_where","targetKind":"block","branch":"true"},{"id":"rl_studentf04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"pace"},"op":"eq","value":"opt_about_right"}],"groups":[]},"from":"pace","target":"most_useful","targetKind":"block","branch":"true"},{"id":"rl_studentf05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"pace"},"op":"eq","value":"opt_too_fast"}],"groups":[]},"from":"pace","target":"fast_where","targetKind":"block","branch":"true"},{"id":"rl_studentf06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"recommend"},"op":"lte","value":6}],"groups":[]},"from":"recommend","target":"what_would_change_it","targetKind":"block","branch":"true"},{"id":"rl_studentf07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"recommend"},"op":"gte","value":7}],"groups":[]},"from":"recommend","target":"quote_ok","targetKind":"block","branch":"true"},{"id":"rl_studentf08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"what_would_change_it","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
