VALUES ('tpl_quiz', 'quiz', 'Knowledge quiz', 'Education', 'A scored quiz that adapts to how the first answers go.', 'Worked example questions with scores already attached to the options, so the wiring is done and you only replace the wording. The warm-up question decides whether the taker gets the easier set or the harder one — which is how a quiz stays interesting for both ends of a class.', '["quiz","scoring","assessment","branching"]', 'ListChecks', 'text', 3, 10, '{"schemaVersion":4,"title":"Knowledge quiz","description":"A scored quiz that adapts to how the first answers go.","blocks":[{"id":"blk_quiz00","ref":"welcome","title":"A short quiz. No pressure — you''ll get your score at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_quiz01","ref":"name","title":"What should we call you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_quiz02","ref":"self_level","title":"How would you describe yourself on this topic?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_starting_out","label":"Just starting out","image_key":null},{"id":"opt_i_know_a","label":"I know a bit","image_key":null},{"id":"opt_i_know_this","label":"I know this well","image_key":null}],"allowOther":false},{"id":"blk_quiz03","ref":"easy_1","title":"Which of these is a primary colour?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_green","label":"Green","image_key":null,"score":0},{"id":"opt_blue","label":"Blue","image_key":null,"score":1},{"id":"opt_orange","label":"Orange","image_key":null,"score":0},{"id":"opt_purple","label":"Purple","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quiz04","ref":"easy_2","title":"Is the Pacific the largest ocean on Earth?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_quiz05","ref":"easy_3","title":"Which of these are mammals? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_dolphin","label":"Dolphin","image_key":null,"score":1},{"id":"opt_shark","label":"Shark","image_key":null,"score":0},{"id":"opt_bat","label":"Bat","image_key":null,"score":1},{"id":"opt_penguin","label":"Penguin","image_key":null,"score":0}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_quiz06","ref":"hard_1","title":"Which of these gases makes up most of Earth''s atmosphere?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_oxygen","label":"Oxygen","image_key":null,"score":0},{"id":"opt_nitrogen","label":"Nitrogen","image_key":null,"score":1},{"id":"opt_carbon_dioxide","label":"Carbon dioxide","image_key":null,"score":0},{"id":"opt_argon","label":"Argon","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quiz07","ref":"hard_2","title":"Put these in order, closest to the Sun first","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_mercury","label":"Mercury"},{"id":"opt_item_earth","label":"Earth"},{"id":"opt_item_jupiter","label":"Jupiter"},{"id":"opt_item_neptune","label":"Neptune"}]},{"id":"blk_quiz08","ref":"hard_3","title":"Name the process plants use to turn light into energy","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_quiz09","ref":"confidence","title":"How confident are you in your answers?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinio