VALUES ('tpl_clientintake', 'client-intake', 'New client intake', 'Services', 'Everything you need before the first client session.', 'Replaces the intake PDF nobody fills in. What someone is here for decides what they are asked next — a one-off project gets scope and budget, an ongoing engagement gets scale and decision-makers, a second opinion gets asked what was said the first time. Signed, and done before the first meeting rather than during it.', '["intake","clients","agency","branching"]', 'ClipboardList', 'text', 4, 18, '{"schemaVersion":4,"title":"New client intake","description":"Everything you need before the first client session.","blocks":[{"id":"blk_clientin00","ref":"welcome","title":"Welcome! A few questions so we''re ready for our first session.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientin01","ref":"contact","title":"Your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_clientin02","ref":"organisation","title":"Which organisation, if any?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_clientin03","ref":"address","title":"Your address","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"]},{"id":"blk_clientin04","ref":"service","title":"What are you here for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_initial_consultation","label":"An initial consultation","image_key":null},{"id":"opt_a_one_off","label":"A one-off project","image_key":null},{"id":"opt_an_ongoing_engagement","label":"An ongoing engagement","image_key":null},{"id":"opt_a_second_opinion","label":"A second opinion","image_key":null}],"allowOther":false},{"id":"blk_clientin05","ref":"consult_topic","title":"What''s the one thing you most want to get out of it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_clientin06","ref":"project_scope","title":"What needs to be delivered?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_clientin07","ref":"project_deadline","title":"Is there a date it has to be done by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_clientin08","ref":"project_budget","title":"What budget are you working with?","description":"A range is fine — it tells us what''s realistic before we spend your time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5k","label":"Under $5k","image_key":null},{"id":"opt_5k_15k","label":"$5k–$15k","image_key":null},{"id":"opt_15k_50k","label":"$15k–$50k","image_key":null},{"id":"opt_50k","label":"$50k+","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather you suggest","image_key":null}],"allowOther":false},{"id":"blk_clientin09","ref":"ongoing_cadence","title":"How often would we work together?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_fortnightly","label":"Fortnightly","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_as_needed","label":"As needed","image_key":null}],"allowOther":false},{"id":"blk_clientin10","ref":"ongoing_stakeholders","title":"Who else would be involved, and who signs things off?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_clientin11","ref":"prior_advice","title":"What were you told, and by whom?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_clientin12","ref":"prior_doubt","title":"What about it didn''t sit right?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_clientin13","ref":"background","title":"Tell us the background in your own words","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_clientin14","ref":"goals","title":"What would a good outcome look like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_clientin15","ref":"urgency","title":"How soon do you need to start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_week","label":"This week","image_key":null},{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_this_quarter","label":"This quarter","image_key":null},{"id":"opt_no_rush","label":"No rush","image_key":null}],"allowOther":false},{"id":"blk_clientin16","ref":"referral","title":"How did you find us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_referral","label":"Referral","image_key":null},{"id":"opt_search","label":"Search","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_existing_client","label":"Existing client","image_key":null}],"allowOther":false},{"id":"blk_clientin17","ref":"documents","title":"Anything we should read first?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","image/*"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_clientin18","ref":"terms","title":"Terms of engagement","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I have read and accept the terms of engagement and the privacy policy.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_clientin01","ref":"end_thanks","title":"Thanks — we''re ready 🤝","bodyMd":"We''ll be in touch to arrange the first session.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_clientin01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"consult_topic","target":"background","targetKind":"block"},{"id":"rl_clientin02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"project_budget","target":"background","targetKind":"block"},{"id":"rl_clientin03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"ongoing_stakeholders","target":"background","targetKind":"block"},{"id":"rl_clientin04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service"},"op":"eq","value":"opt_an_initial_consultation"}],"groups":[]},"from":"service","target":"consult_topic","targetKind":"block","branch":"true"},{"id":"rl_clientin05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service"},"op":"eq","value":"opt_a_one_off"}],"groups":[]},"from":"service","target":"project_scope","targetKind":"block","branch":"true"},{"id":"rl_clientin06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service"},"op":"eq","value":"opt_an_ongoing_engagement"}],"groups":[]},"from":"service","target":"ongoing_cadence","targetKind":"block","branch":"true"},{"id":"rl_clientin07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service"},"op":"eq","value":"opt_a_second_opinion"}],"groups":[]},"from":"service","target":"prior_advice","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
