VALUES ('tpl_appointmentbooking', 'appointment-booking', 'Appointment booking', 'Services', 'Take a booking with the right slot length for the reason.', 'A date block with time turned on, so the answer is an appointment rather than a day. First visits are asked the questions a first visit needs; something urgent is offered the next available slot instead of a calendar; a routine check is three taps. Slot length stops being a guess.', '["booking","appointments","scheduling","branching"]', 'CalendarClock', 'text', 4, 15, '{"schemaVersion":4,"title":"Appointment booking","description":"Take a booking with the right slot length for the reason.","blocks":[{"id":"blk_appointm00","ref":"welcome","title":"Let''s find you a time.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_appointm01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_appointm02","ref":"phone","title":"Best number to reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false},{"id":"blk_appointm03","ref":"email","title":"Email, for the confirmation?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_appointm04","ref":"reason","title":"What''s the appointment for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_first_consultation","label":"First consultation","image_key":null},{"id":"opt_follow_up","label":"Follow-up","image_key":null},{"id":"opt_routine_check","label":"Routine check","image_key":null},{"id":"opt_something_urgent","label":"Something urgent","image_key":null}],"allowOther":false},{"id":"blk_appointm05","ref":"first_concern","title":"What would you like to talk about?","description":"A sentence or two. It decides how long we book you in for.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_appointm06","ref":"referred_by","title":"Were you referred by anyone?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_appointm07","ref":"date_of_birth","title":"Date of birth, for your record","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"DD/MM/YYYY","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_appointm08","ref":"previous_visit","title":"Roughly when were you last in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_appointm09","ref":"since_then","title":"What''s changed since then?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_appointm10","ref":"urgent_detail","title":"Tell us what''s happening","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_appointm11","ref":"urgent_today","title":"Do you need to be seen today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, today","noLabel":"The next few days is fine"},{"id":"blk_appointm12","ref":"preferred_slot","title":"When suits you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"17:30"},{"id":"blk_appointm13","ref":"backup_slot","title":"And a second choice, in case that''s taken?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"17:30"},{"id":"blk_appointm14","ref":"access_needs","title":"Anything we should arrange for your visit?","description":"Step-free access, an interpreter, a longer appointment — just say.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_appointm15","ref":"notes","title":"Anything else we should know beforehand?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_appointm01","ref":"end_thanks","title":"Booked 🗓️","bodyMd":"We''ll confirm by text shortly.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_appointm02","ref":"end_urgent","title":"We''ll call you back within the hour ☎️","bodyMd":"Keep your phone nearby. If it''s an emergency, please don''t wait for us — call your local emergency number.","imageUrl":null,"redirectDelaySec":5,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_appointm01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"date_of_birth","target":"preferred_slot","targetKind":"block"},{"id":"rl_appointm02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"since_then","target":"preferred_slot","targetKind":"block"},{"id":"rl_appointm03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_first_consultation"}],"groups":[]},"from":"reason","target":"first_concern","targetKind":"block","branch":"true"},{"id":"rl_appointm04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_follow_up"}],"groups":[]},"from":"reason","target":"previous_visit","targetKind":"block","branch":"true"},{"id":"rl_appointm05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_routine_check"}],"groups":[]},"from":"reason","target":"preferred_slot","targetKind":"block","branch":"true"},{"id":"rl_appointm06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_something_urgent"}],"groups":[]},"from":"reason","target":"urgent_detail","targetKind":"block","branch":"true"},{"id":"rl_appointm07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgent_today"},"op":"eq","value":true}],"groups":[]},"from":"urgent_today","target":"end_urgent","targetKind":"ending","branch":"true"},{"id":"rl_appointm08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgent_today"},"op":"eq","value":false}],"groups":[]},"from":"urgent_today","target":"preferred_slot","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved — picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped — your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#FD6F29","accentText":"#201a16","botBubble":"#ffffff","userBubble":"#C9AEEE","userBubbleText":"#201a16","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
