VALUES ('tpl_volunteersignup', 'volunteer-signup', 'Volunteer signup', 'Community', 'Match volunteers to shifts they can actually make.', 'Availability and skills as structured choices, so a coordinator fills a rota by filtering rather than by reading. Anyone offering to drive is asked about their licence and insurance; anyone offering to work with people directly is asked about their DBS check — the two questions that otherwise hold up a whole rota.', '["volunteers","nonprofit","rota","branching"]', 'HandHeart', 'content', 5, 18, '{"schemaVersion":4,"title":"Volunteer signup","description":"Match volunteers to shifts they can actually make.","blocks":[{"id":"blk_voluntee00","ref":"welcome","title":"Thanks for offering to help! Tell us when you''re free and what you''d like to do.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_voluntee01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_voluntee02","ref":"email","title":"Email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_voluntee03","ref":"phone","title":"Mobile number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false},{"id":"blk_voluntee04","ref":"over_18","title":"Are you over 18?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_voluntee05","ref":"guardian_contact","title":"A parent or guardian''s name and number","description":"We need this before you can be put on a shift.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk