VALUES ('tpl_membershipapplication', 'membership-application', 'Membership application', 'Community', 'Take applications with the tier, the evidence and the terms in one pass.', 'Everything a membership secretary would otherwise chase over three emails. A concession is asked for the evidence that supports it, a household membership for the other names on it, and a life membership is handed straight to the committee — so the reply is a decision rather than another question.', '["membership","club","community","branching"]', 'BadgeCheck', 'content', 4, 16, '{"schemaVersion":4,"title":"Membership application","description":"Take applications with the tier, the evidence and the terms in one pass.","blocks":[{"id":"blk_membersh00","ref":"welcome","title":"Glad you want to join us. A few questions and we''ll take it from there.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_membersh01","ref":"name","title":"Your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_membersh02","ref":"email","title":"Email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false},{"id":"blk_membersh03","ref":"phone","title":"Phone number?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false},{"id":"blk_membersh04","ref":"date_of_birth","title":"Date of birth","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"DD/MM/YYYY","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_membersh05","ref":"address","title":"Your address","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"]},{"id":"blk_membersh06","ref":"tier","title":"Which membership?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_standard","label":"Standard","description":"Full access, billed yearly","image_key":null},{"id":"opt_concession","label":"Concession","description":"Students, over-65s and unwaged","image_key":null},{"id":"opt_household","label":"Household","description":"Up to four people at one address","image_key":null},{"id":"opt_life_member","label":"Life member","image_key":null}],"allowOther":false},{"id":"blk_membersh07","ref":"concession_basis","title":"Which applies to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_student","label":"Student","image_key":null},{"id":"opt_over_65","label":"Over 65","image_key":null},{"id":"opt_unwaged","label":"Unwaged","image_key":null},{"id":"opt_receiving_benefits","label":"Receiving benefits","image_key":null}],"allowOther":false},{"id":"blk_membersh08","ref":"concession_evidence","title":"Something that shows it","description":"A student card, a letter, a screenshot — anything dated in the last year.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":2,"maxSizeMB":10},{"id":"blk_membersh09","ref":"household_members","title":"Who else is on it? One name per line.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_membersh10","ref":"household_count","title":"How many people in total, including you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":2,"max":4,"integerOnly":true},{"id":"blk_membersh11","ref":"life_nominator","title":"Which existing member is nominating you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_membersh12","ref":"life_contribution","title":"What''s your history with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_membersh13","ref":"motivation","title":"Why would you like to join?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_membersh14","ref":"interests","title":"What would you like to get involved in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_regular_meetups","label":"Regular meetups","image_key":null},{"id":"opt_the_annual_gathering","label":"The annual gathering","image_key":null},{"id":"opt_volunteering","label":"Volunteering","image_key":null},{"id":"opt_the_committee","label":"The committee","image_key":null},{"id":"opt_just_the_newsletter","label":"Just the newsletter, thanks","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_membersh15","ref":"how_heard","title":"How did you hear about us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_member","label":"A member","image_key":null},{"id":"opt_an_event","label":"An event","image_key":null},{"id":"opt_online","label":"Online","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}],"allowOther":false},{"id":"blk_membersh16","ref":"code_of_conduct","title":"Code of conduct","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I have read the code of conduct and agree to abide by it as a 