VALUES ('tpl_testimonialrequest', 'testimonial-request', 'Testimonial request', 'Community', 'Collect quotes you''re actually allowed to publish.', 'Most testimonials never get used because nobody asked permission in writing. The quote, the attribution and the consent are collected together — and how they want to be credited decides what else is asked, so an anonymous quote is never chased for a headshot.', '["testimonial","social proof","marketing","branching"]', 'Quote', 'content', 4, 13, '{"schemaVersion":4,"title":"Testimonial request","description":"Collect quotes you''re actually allowed to publish.","blocks":[{"id":"blk_testimon00","ref":"welcome","title":"Would you say a few words about working with us? It really helps.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_testimon01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_testimon02","ref":"rating","title":"How would you rate your experience?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_testimon03","ref":"worked_on","title":"What did we work on together?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":500},{"id":"blk_testimon04","ref":"quote","title":"In your own words — what was it like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_testimon05","ref":"before_after","title":"What was it like before, and what changed?","description":"The most useful testimonials are the ones with a before in them.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media