-- Retire official templates that have left the catalogue. Never touches
-- templates an organization saved for itself.
DELETE FROM form_templates WHERE official = 1 AND organization_id IS NULL AND id NOT IN ('tpl_leadcapture', 'tpl_demorequest', 'tpl_quoterequest', 'tpl_partnershipinquiry', 'tpl_npssurvey', 'tpl_csatsurvey', 'tpl_productmarketfit', 'tpl_featurerequest', 'tpl_betasignup', 'tpl_cancellationsurvey', 'tpl_waitlist', 'tpl_newslettersignup', 'tpl_webinarregistration', 'tpl_contentdownload', 'tpl_eventrsvp', 'tpl_eventfeedback', 'tpl_speakersubmission', 'tpl_workshopregistration', 'tpl_jobapplication', 'tpl_employeeonboarding', 'tpl_exitinterview', 'tpl_engagementpulse', 'tpl_referralsubmission', 'tpl_bugreport', 'tpl_supportticket', 'tpl_contactus', 'tpl_refundrequest', 'tpl_courseenrollment', 'tpl_studentfeedback', 'tpl_quiz', 'tpl_clientintake', 'tpl_appointmentbooking', 'tpl_volunteersignup', 'tpl_membershipapplication', 'tpl_testimonialrequest');
